	// clip is stamped with. Nothing later -- upload, transcription -- is
	// early enough to be safe.
	recordingEpoch = turnEpoch;
	recorder.start();
	starting = false;
	setRecordingUI(true);
	statusEl.textContent =
		"Recording... Send when you are done, Discard to throw it away.";
