    async fn set_active_session(&self, session: Option<PiSession>) {
        *self.active_session.lock().await = session;
    }

    pub fn route(&self) -> &str {
        &self.route
    }
    pub fn activity_clock(&self) -> ActivityClock {
        self.last_activity.clone()
    }
    pub fn live_leg_state(&self) -> LiveLegState {
        self.live_leg.clone()
    }
    pub fn touch_activity(&self) {
        self.last_activity.touch();
    }
    pub fn status(&self) -> serde_json::Value {
        let spec = if self.route == OPERATOR {
            self.operator_model.clone().unwrap_or_default()
        } else {
            self.model_spec.clone()
        };
        let (provider, model, requested) = crate::models::parse_spec(&spec);
        let model_name = if provider.is_empty() {
            model.clone()
        } else {
            format!("{provider}/{model}")
        };
        let effective = self.live_leg.effective_thinking();
        let models = if self.route == OPERATOR {
            Vec::new()
        } else if let Some(project) = &self.project {
            let key = format!(
                "{}\0{}",
                project.host.as_deref().unwrap_or(""),
                project.runtime
            );
            self.catalogs
                .get(&key)
                .map(|catalog| {
                    catalog
                        .entries
                        .iter()
                        .map(|entry| {
                            serde_json::json!({
                                "provider": entry.provider,
                                "model": entry.model,
                                "thinks": entry.thinks,
                            })
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        serde_json::json!({"type":"status", "route":self.route, "label":self.route_label(), "model":spec, "model_name":model_name, "thinking":if effective.is_empty() { requested.clone() } else { effective.clone() }, "thinking_requested":requested, "thinking_confirmed":!effective.is_empty(), "thinking_default":self.agent_thinking, "levels":THINKING_LEVELS, "models":models, "model_swaps":self.model_swaps, "projects":self.registry.ids()})
    }
    pub fn route_label(&self) -> String {
        if self.route == OPERATOR {
            "Operator".into()
        } else {
            self.project
                .as_ref()
                .map(|p| p.id.clone())
                .unwrap_or_else(|| self.route.clone())
        }
    }
    pub fn report_leg_state(&self, thinking: &str) -> bool {
        self.live_leg.report_thinking(thinking)
    }
    pub async fn shutdown(&mut self) {
        if let Some(session) = self.agent.take() {
            session.close().await;
        }
        if let Some(session) = self.operator.take() {
            session.close().await;
        }
        self.set_active_session(None).await;
    }

